VAR_INV_ITEMS_DATA   EQU $C880+$388   ; Mutable array 'INV_ITEMS' data (8 elements x 2 bytes) (16 bytes)
PSG_MUSIC_PTR        EQU $C880+$398   ; PSG music data pointer (2 bytes)
PSG_MUSIC_START      EQU $C880+$39A   ; PSG music start pointer (for loops) (2 bytes)
PSG_MUSIC_ACTIVE     EQU $C880+$39C   ; PSG music active flag (1 bytes)
PSG_IS_PLAYING       EQU $C880+$39D   ; PSG playing flag (1 bytes)
PSG_DELAY_FRAMES     EQU $C880+$39E   ; PSG frame delay counter (1 bytes)
PSG_MUSIC_BANK       EQU $C880+$39F   ; PSG music bank ID (for multibank) (1 bytes)
SFX_PTR              EQU $C880+$3A0   ; SFX data pointer (2 bytes)
SFX_ACTIVE           EQU $C880+$3A2   ; SFX active flag (1 bytes)
SFX_BANK             EQU $C880+$3A3   ; SFX bank ID (for multibank) (1 bytes)
VAR_ARG0             EQU $C880+$3A4   ; Function argument 0 (16-bit) (2 bytes)
VAR_ARG1             EQU $C880+$3A6   ; Function argument 1 (16-bit) (2 bytes)
VAR_ARG2             EQU $C880+$3A8   ; Function argument 2 (16-bit) (2 bytes)
VAR_ARG3             EQU $C880+$3AA   ; Function argument 3 (16-bit) (2 bytes)
VAR_ARG4             EQU $C880+$3AC   ; Function argument 4 (16-bit) (2 bytes)
CURRENT_ROM_BANK     EQU $C880+$3AE   ; Current ROM bank ID (multibank tracking) (1 bytes)
; Array length constants
ARRAY_ITEM_WEIGHT_LEN         EQU 8   ; 8 elements
ARRAY_ENT_HS_X_LEN         EQU 4   ; 4 elements
ARRAY_ENT_HS_Y_LEN         EQU 4   ; 4 elements
ARRAY_ENT_HS_W_LEN         EQU 4   ; 4 elements
ARRAY_ENT_HS_H_LEN         EQU 4   ; 4 elements
ARRAY_CLOCK_HS_X_LEN         EQU 6   ; 6 elements
ARRAY_CLOCK_HS_Y_LEN         EQU 6   ; 6 elements
ARRAY_CLOCK_HS_W_LEN         EQU 6   ; 6 elements
ARRAY_CLOCK_HS_H_LEN         EQU 6   ; 6 elements
ARRAY_ANT_HS_X_LEN         EQU 4   ; 4 elements
ARRAY_ANT_HS_Y_LEN         EQU 4   ; 4 elements
ARRAY_ANT_HS_W_LEN         EQU 4   ; 4 elements
ARRAY_ANT_HS_H_LEN         EQU 4   ; 4 elements
ARRAY_WGT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_CONS_HS_X_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_Y_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_W_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_H_LEN         EQU 1   ; 1 elements
ARRAY_VAULT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_NPC_STATE_LEN         EQU 4   ; 4 elements
ARRAY_INV_ITEMS_LEN         EQU 8   ; 8 elements

;***************************************************************************
; ARRAY DATA (ROM literals)
;***************************************************************************
; Arrays are stored in ROM and accessed via pointers
; At startup, main() initializes VAR_{name} to point to ARRAY_{name}_DATA

; Array literal for variable 'ITEM_WEIGHT' (8 elements, 2 bytes each)
MAIN:
    ; Initialize global variables
    CLR VPY_MOVE_X        ; MOVE offset defaults to 0
    CLR VPY_MOVE_Y        ; MOVE offset defaults to 0
    LDA #$F8
    STA TEXT_SCALE_H      ; Default height = -8 (normal size)
    LDA #$48
    STA TEXT_SCALE_W      ; Default width = 72 (normal size)
    LDA #$7F
    STA DRAW_SCALE        ; Default T1 scale = $7F (127 = full BIOS scale)
    LDD #0  ; const STATE_TITLE
    STD VAR_SCREEN
    LDD #0
    STD VAR_BLINK_TIMER
    LDD #0
    STD VAR_BLINK_ON
    LDD #0
    STD VAR_INTRO_PAGE
    LDD #0  ; const ROOM_ENTRANCE
    STD VAR_CURRENT_ROOM
    LDD #0
    STD VAR_PLAYER_X
    LDD #-115
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_SCROLL_X
    LDD #5
    STD VAR_PLAYER_SPEED
    LDD #0  ; const VERB_EXAMINE
    STD VAR_CURRENT_VERB
    LDD #-1
    STD VAR_NEAR_HS
    LDD #0
    STD VAR_MSG_ID
    LDD #0
    STD VAR_MSG_TIMER
    LDD #0
    STD VAR_ROOM_EXIT
    LDD #0
    STD VAR_FLAGS_A
    LDD #0
    STD VAR_FLAGS_B
    ; Copy array 'NPC_STATE' from ROM to RAM (4 elements)
    LDX #ARRAY_NPC_STATE_DATA       ; Source: ROM array data
    LDU #VAR_NPC_STATE_DATA       ; Dest: RAM array space
    LDD #4        ; Number of elements
.COPY_LOOP_0:
    LDY ,X++        ; Load word from ROM, increment source
    STY ,U++        ; Store word to RAM, increment dest
    SUBD #1         ; Decrement counter
    LBNE .COPY_LOOP_0 ; Loop until done (LBNE for long branch)
    LDX #VAR_NPC_STATE_DATA    ; Array now in RAM
    STX VAR_NPC_STATE
    LDD #1
    STD VAR_EXIT_ROOM_TARGET
    LDD #0  ; const MUSIC_NONE
    STD VAR_CURRENT_MUSIC
    LDD #0
    STD VAR_BTN1_FIRED
    LDD #0
    STD VAR_BTN2_FIRED
    LDD #0
    STD VAR_BTN3_FIRED
    LDD #0
    STD VAR_PREV_BTN1
    LDD #0
    STD VAR_PREV_BTN2
    LDD #0
    STD VAR_PREV_BTN3
    ; Copy array 'INV_ITEMS' from ROM to RAM (8 elements)
    LDX #ARRAY_INV_ITEMS_DATA       ; Source: ROM array data
    LDU #VAR_INV_ITEMS_DATA       ; Dest: RAM array space
    LDD #8        ; Number of elements
.COPY_LOOP_1:
    LDY ,X++        ; Load word from ROM, increment source
    STY ,U++        ; Store word to RAM, increment dest
    SUBD #1         ; Decrement counter
    LBNE .COPY_LOOP_1 ; Loop until done (LBNE for long branch)
    LDX #VAR_INV_ITEMS_DATA    ; Array now in RAM
    STX VAR_INV_ITEMS
    LDD #0
    STD VAR_INV_COUNT
    LDD #0
    STD VAR_INV_WEIGHT
    LDD #0
    STD VAR_SHOW_INVENTORY
    LDD #-1
    STD VAR_ACTIVE_ITEM
    LDD #0
    STD VAR_INV_CURSOR
    LDD #60
    STD VAR_HEARTBEAT_TEMPO
    LDD #0
    STD VAR_HEARTBEAT_TIMER
    LDD #-110
    STD VAR_TESTAMENT_Y
    LDD #0
    STD VAR_TESTAMENT_PAGE
    LDD #-110
    STD VAR_ENDING_Y
    LDD #0
    STD VAR_SKIPPEDFRAMES
    ; === Initialize Joystick (one-time setup) ===
    JSR $F1AF    ; DP_to_C8 (required for RAM access)
    CLR $C823    ; CRITICAL: Clear analog mode flag (Joy_Analog does DEC on this)
    LDA #$01     ; CRITICAL: Resolution threshold (power of 2: $40=fast, $01=accurate)
    STA $C81A    ; Vec_Joy_Resltn (loop terminates when B=this value after LSRBs)
    LDA #$01
    STA $C81F    ; Vec_Joy_Mux_1_X (enable X axis reading)
    LDA #$03
    STA $C820    ; Vec_Joy_Mux_1_Y (enable Y axis reading)
    LDA #$00
    STA $C821    ; Vec_Joy_Mux_2_X (disable joystick 2 - CRITICAL!)
    STA $C822    ; Vec_Joy_Mux_2_Y (disable joystick 2 - saves cycles)
    ; Mux configured - J1_X()/J1_Y() can now be called

    ; Call main() for initialization
    ; ===== LOAD_LEVEL builtin =====
    ; Load level: 'entrance'
    ; Level asset index: 3 (multibank)
    LDX #3
    JSR LOAD_LEVEL_BANKED
    ; TODO: Statement Pass { source_line: 213 }

.MAIN_LOOP:
    JSR LOOP_BODY
    LBRA .MAIN_LOOP   ; Use long branch for multibank support

LOOP_BODY:
    JSR Wait_Recal   ; Synchronize with screen refresh (mandatory)
    JSR $F1BA    ; Read_Btns: PSG reg14 -> $C80F (active-HIGH), edge -> $C811
    LDD #0  ; const MUSIC_NONE
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDB >VAR_CURRENT_MUSIC
    SEX             ; Sign-extend B -> D
    CMPD TMPVAL
    LBEQ .CMP_0_TRUE
    LDD #0
    LBRA .CMP_0_END
.CMP_0_TRUE:
    LDD #1
.CMP_0_END:
    LBEQ IF_NEXT_1
    LDD #1  ; const MUSIC_TITLE
    STB VAR_CURRENT_MUSIC
    ; PLAY_MUSIC("intro") - play music asset (index=1)
    LDX #1        ; Music asset index for lookup
    JSR PLAY_MUSIC_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_0
IF_NEXT_1:
IF_END_0:
    LDD #10
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SKIPPEDFRAMES
    CMPD TMPVAL
    LBLT .CMP_1_TRUE
    LDD #0
    LBRA .CMP_1_END
.CMP_1_TRUE:
    LDD #1
.CMP_1_END:
    LBEQ IF_NEXT_3
    LDD >VAR_SKIPPEDFRAMES
    STD TMPVAL          ; Save left operand
    LDD #1
    ADDD TMPVAL         ; D = D + TMPVAL
    STD VAR_SKIPPEDFRAMES
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    LBNE .J1B1_0_ON
    LDD #0
    LBRA .J1B1_0_END
.J1B1_0_ON:
    LDD #1
.J1B1_0_END:
    STD RESULT
    STD VAR_PREV_BTN1
    LDA >$C80F   ; Vec_Btns_1: bit1=1 means btn2 pressed
    BITA #$02
    LBNE .J1B2_1_ON
    LDD #0
    LBRA .J1B2_1_END
.J1B2_1_ON:
    LDD #1
.J1B2_1_END:
    STD RESULT
    STD VAR_PREV_BTN2
    LDA >$C80F   ; Vec_Btns_1: bit2=1 means btn3 pressed
    BITA #$04
    LBNE .J1B3_2_ON
    LDD #0
    LBRA .J1B3_2_END
.J1B3_2_ON:
    LDD #1
.J1B3_2_END:
    STD RESULT
    STD VAR_PREV_BTN3
    RTS
    LBRA IF_END_2
IF_NEXT_3:
IF_END_2:
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    LBNE .J1B1_3_ON
    LDD #0
    LBRA .J1B1_3_END
.J1B1_3_ON:
    LDD #1
.J1B1_3_END:
    STD RESULT
    STD VAR_RAW1
    LDA >$C80F   ; Vec_Btns_1: bit1=1 means btn2 pressed
    BITA #$02
    LBNE .J1B2_4_ON
    LDD #0
    LBRA .J1B2_4_END
.J1B2_4_ON:
    LDD #1
.J1B2_4_END:
    STD RESULT
    STD VAR_RAW2
    LDA >$C80F   ; Vec_Btns_1: bit2=1 means btn3 pressed
    BITA #$04
    LBNE .J1B3_5_ON
    LDD #0
    LBRA .J1B3_5_END
.J1B3_5_ON:
    LDD #1
.J1B3_5_END:
    STD RESULT
    STD VAR_RAW3
    LDD #0
    STD VAR_BTN1_FIRED
    LDD #0
    STD VAR_BTN2_FIRED
    LDD #0
    STD VAR_BTN3_FIRED
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW1
    CMPD TMPVAL
    LBEQ .CMP_3_TRUE
    LDD #0
    LBRA .CMP_3_END
.CMP_3_TRUE:
    LDD #1
.CMP_3_END:
    LBEQ .LOGIC_2_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN1
    CMPD TMPVAL
    LBEQ .CMP_4_TRUE
    LDD #0
    LBRA .CMP_4_END
.CMP_4_TRUE:
    LDD #1
.CMP_4_END:
    LBEQ .LOGIC_2_FALSE
    LDD #1
    LBRA .LOGIC_2_END
.LOGIC_2_FALSE:
    LDD #0
.LOGIC_2_END:
    LBEQ IF_NEXT_5
    LDD #1
    STD VAR_BTN1_FIRED
    LBRA IF_END_4
IF_NEXT_5:
IF_END_4:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW2
    CMPD TMPVAL
    LBEQ .CMP_6_TRUE
    LDD #0
    LBRA .CMP_6_END
.CMP_6_TRUE:
    LDD #1
.CMP_6_END:
    LBEQ .LOGIC_5_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN2
    CMPD TMPVAL
    LBEQ .CMP_7_TRUE
    LDD #0
    LBRA .CMP_7_END
.CMP_7_TRUE:
    LDD #1
.CMP_7_END:
    LBEQ .LOGIC_5_FALSE
    LDD #1
    LBRA .LOGIC_5_END
.LOGIC_5_FALSE:
    LDD #0
.LOGIC_5_END:
    LBEQ IF_NEXT_7
    LDD #1
    STD VAR_BTN2_FIRED
    LBRA IF_END_6
IF_NEXT_7:
IF_END_6:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW3
    CMPD TMPVAL
    LBEQ .CMP_9_TRUE
    LDD #0
    LBRA .CMP_9_END
.CMP_9_TRUE:
    LDD #1
.CMP_9_END:
    LBEQ .LOGIC_8_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN3
    CMPD TMPVAL
    LBEQ .CMP_10_TRUE
    LDD #0
    LBRA .CMP_10_END
.CMP_10_TRUE:
    LDD #1
.CMP_10_END:
    LBEQ .LOGIC_8_FALSE
    LDD #1
    LBRA .LOGIC_8_END
.LOGIC_8_FALSE:
    LDD #0
.LOGIC_8_END:
    LBEQ IF_NEXT_9
    LDD #1
    STD VAR_BTN3_FIRED
    LBRA IF_END_8
IF_NEXT_9:
IF_END_8:
    LDD >VAR_RAW1
    STD VAR_PREV_BTN1
    LDD >VAR_RAW2
    STD VAR_PREV_BTN2
    LDD >VAR_RAW3
    STD VAR_PREV_BTN3
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_11_TRUE
    LDD #0
    LBRA .CMP_11_END
.CMP_11_TRUE:
    LDD #1
.CMP_11_END:
    LBEQ IF_NEXT_11
    LDD >VAR_HEARTBEAT_TIMER
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #1
    ADDD TMPVAL         ; D = D + LEFT (from TMPVAL)
    STD VAR_HEARTBEAT_TIMER
    LDD >VAR_HEARTBEAT_TEMPO
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_HEARTBEAT_TIMER
    CMPD TMPVAL
    LBGE .CMP_12_TRUE
    LDD #0
    LBRA .CMP_12_END
.CMP_12_TRUE:
    LDD #1
.CMP_12_END:
    LBEQ IF_NEXT_13
    LDD #0
    STD VAR_HEARTBEAT_TIMER
    LBRA IF_END_12
IF_NEXT_13:
IF_END_12:
    LBRA IF_END_10
IF_NEXT_11:
IF_END_10:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BTN2_FIRED
    CMPD TMPVAL
    LBEQ .CMP_13_TRUE
    LDD #0
    LBRA .CMP_13_END
.CMP_13_TRUE:
    LDD #1
.CMP_13_END:
    LBEQ IF_NEXT_15
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_14_TRUE
    LDD #0
    LBRA .CMP_14_END
.CMP_14_TRUE:
    LDD #1
.CMP_14_END:
    LBEQ IF_NEXT_17
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOW_INVENTORY
    CMPD TMPVAL
    LBEQ .CMP_15_TRUE
    LDD #0
    LBRA .CMP_15_END
.CMP_15_TRUE:
    LDD #1
.CMP_15_END:
    LBEQ IF_NEXT_19
    LDD #1
    STD VAR_SHOW_INVENTORY
    LBRA IF_END_18
IF_NEXT_19:
    LDD #0
    STD VAR_SHOW_INVENTORY
IF_END_18:
    LBRA IF_END_16
IF_NEXT_17:
IF_END_16:
    LBRA IF_END_14
IF_NEXT_15:
IF_END_14:
    LDD #0  ; const STATE_TITLE
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_16_TRUE
    LDD #0
    LBRA .CMP_16_END
.CMP_16_TRUE:
    LDD #1
.CMP_16_END:
    LBEQ IF_NEXT_21
    JSR DRAW_TITLE
    LBRA IF_END_20
IF_NEXT_21:
    LDD #1  ; const STATE_INTRO
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_17_TRUE
    LDD #0
    LBRA .CMP_17_END
.CMP_17_TRUE:
    LDD #1
.CMP_17_END:
    LBEQ IF_NEXT_22
    JSR DRAW_INTRO
    LBRA IF_END_20
IF_NEXT_22:
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_18_TRUE
    LDD #0
    LBRA .CMP_18_END
.CMP_18_TRUE:
    LDD #1
.CMP_18_END:
    LBEQ IF_NEXT_23
    JSR TRAMP_UPDATE_ROOM  ; cross-bank trampoline (bank #0 -> bank #1)
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOW_INVENTORY
    CMPD TMPVAL
    LBEQ .CMP_19_TRUE
    LDD #0
    LBRA .CMP_19_END
.CMP_19_TRUE:
    LDD #1
.CMP_19_END:
    LBEQ IF_NEXT_25
    JSR DRAW_INVENTORY
    LBRA IF_END_24
IF_NEXT_25:
    JSR DRAW_ROOM
IF_END_24:
    LBRA IF_END_20
IF_NEXT_23:
    LDD #4  ; const STATE_TESTAMENT
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_20_TRUE
    LDD #0
    LBRA .CMP_20_END
.CMP_20_TRUE:
    LDD #1
.CMP_20_END:
    LBEQ IF_NEXT_26
    JSR DRAW_TESTAMENT
    LBRA IF_END_20
IF_NEXT_26:
    LDD #3  ; const STATE_ENDING
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_21_TRUE
    LDD #0
    LBRA .CMP_21_END
.CMP_21_TRUE:
    LDD #1
.CMP_21_END:
    LBEQ IF_END_20
    JSR DRAW_ENDING
    LBRA IF_END_20
IF_END_20:
    JSR AUDIO_UPDATE  ; Auto-injected: update music + SFX (after all game logic)
    RTS

; Function: DRAW_TITLE (Bank #0)
DRAW_TITLE:
    ; DRAW_VECTOR_EX: Draw vector asset with transformations
    ; Asset: crypt_logo (index=3, 40 paths) with mirror + intensity
    LDD #0
    TFR B,A       ; X position (low byte) — B already holds it
    STA DRAW_VEC_X
    LDD #10
    TFR B,A       ; Y position (low byte) — B already holds it
    STA DRAW_VEC_Y
    LDD #0
    ; Decode mirror mode into separate flags:
    CLR MIRROR_X  ; Clear X flag
    CLR MIRROR_Y  ; Clear Y flag
    CMPB #1       ; Check if X-mirror (mode 1)
    LBNE .DSVEX_6_CHK_Y
    LDA #1
    STA MIRROR_X
.DSVEX_6_CHK_Y:
    CMPB #2       ; Check if Y-mirror (mode 2)
    LBNE .DSVEX_6_CHK_XY
    LDA #1
    STA MIRROR_Y
.DSVEX_6_CHK_XY:
    CMPB #3       ; Check if both-mirror (mode 3)
    LBNE .DSVEX_6_CALL
    LDA #1
    STA MIRROR_X
    STA MIRROR_Y
.DSVEX_6_CALL:
    ; Set intensity override for drawing
    LDD #0
    TFR B,A       ; Intensity (0-127) — B already holds it
    STA DRAW_VEC_INTENSITY  ; Store intensity override
    LDX #3        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    CLR DRAW_VEC_INTENSITY  ; Clear intensity override for next draw
    LDD #0
    STD RESULT
    LDD >VAR_BLINK_TIMER
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #1
    ADDD TMPVAL         ; D = D + LEFT (from TMPVAL)
    STD VAR_BLINK_TIMER
    LDD #40
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BLINK_TIMER
    CMPD TMPVAL
    LBGE .CMP_22_TRUE
    LDD #0
    LBRA .CMP_22_END
.CMP_22_TRUE:
    LDD #1
.CMP_22_END:
    LBEQ IF_NEXT_28
    LDD #0
    STD VAR_BLINK_TIMER
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BLINK_ON
    CMPD TMPVAL
    LBEQ .CMP_23_TRUE
    LDD #0
    LBRA .CMP_23_END
.CMP_23_TRUE:
    LDD #1
.CMP_23_END:
    LBEQ IF_NEXT_30
    LDD #1
    STD VAR_BLINK_ON
    LBRA IF_END_29
IF_NEXT_30:
    LDD #0
    STD VAR_BLINK_ON
IF_END_29:
    LBRA IF_END_27
IF_NEXT_28:
IF_END_27:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BLINK_ON
    CMPD TMPVAL
    LBEQ .CMP_24_TRUE
    LDD #0
    LBRA .CMP_24_END
